// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILineAxis {
    function approve(address spender, uint256 value) external;
    function allowance(address owner, address spender) external view returns (uint256);
}

// Standard ERC20 interface that compliant contracts would use
interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

// A simple spender contract that adheres to the ERC20 standard
// by expecting a boolean return from transferFrom.
contract Spender {
    function doTransferFrom(address tokenAddress, address from, address to, uint256 amount) public {
        require(IERC20(tokenAddress).transferFrom(from, to, amount), "transferFrom failed");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);
    ILineAxis internal token = ILineAxis(TARGET);
    Spender internal spender;

    address internal SPENDER_CONTRACT_ADDRESS;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, address(this), 100 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        uint256 approvalAmount = 10 * 1e18;

        spender = new Spender();
        SPENDER_CONTRACT_ADDRESS = address(spender);

        token.approve(SPENDER_CONTRACT_ADDRESS, approvalAmount);

        assertEq(token.allowance(attacker, SPENDER_CONTRACT_ADDRESS), approvalAmount, "Allowance was not set correctly");

        // The Spender contract expects a `bool` return from transferFrom, according to the ERC20 standard.
        // The target contract's transferFrom does not return anything.
        // This mismatch will cause the call to revert.
        vm.expectRevert();
        spender.doTransferFrom(TARGET, attacker, address(0xdead), 1 ether);

        // The oracle checks that the allowance is still > 0, which it is because the transfer failed.
        assertGt(token.allowance(attacker, SPENDER_CONTRACT_ADDRESS), 0, "Allowance should not have been spent");
        assertGt(token.allowance(attacker, SPENDER_CONTRACT_ADDRESS), 0, "Logic Exploit Failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

